theorem MIPRE.LowDegree.BinaryPolynomial.oddExtensionLowerBits_spec (q e : ℕ) (hq : q.Prime) (hq2 : q ≠ 2) :
    let a := oddExtensionBits (unary q) (unary (q ^ e))
    let p := oddExtensionLowerBits (unary q) (unary (q ^ e))
    p.length = (polyOfBits a).natDegree ∧ polyOfBits a = polyOfBits (p ++ [true]) ∧ p ≠ [] := by sorry
